{
  "name": "横河 AQ6370 光学频谱分析仪",
  "name_en": "Yokogawa AQ6370 Optical Spectrum Analyzer",
  "manufacturer": "Yokogawa",
  "description": "这是一种台式光学频谱分析仪，用于测量光信号随波长变化的功率或强度分布。实验室中常用于激光器、光纤器件和光通信光源的光谱表征，以及中心波长、谱宽和谱线形状分析。",
  "description_en": "This is a benchtop optical spectrum analyzer used to measure the power or intensity distribution of optical signals versus wavelength. In laboratories, it is commonly used for spectral characterization of lasers, fiber-optic components, and optical communication sources, including center wavelength, spectral width, and lineshape analysis.",
  "actions": [
    {
      "action_name": "auto-bandwidth",
      "description": "获取/设置光谱分辨带宽",
      "description_en": "get/set the spectral resolution bandwidth"
    },
    {
      "action_name": "auto-data",
      "description": "获取光谱数据的纵轴数据",
      "description_en": "get the y-axis spectral data"
    },
    {
      "action_name": "auto-start_sweep",
      "description": "启动一次光谱扫描",
      "description_en": "start a spectrum sweep"
    },
    {
      "action_name": "auto-start_wl",
      "description": "获取/设置扫描起始波长",
      "description_en": "get/set the sweep start wavelength"
    },
    {
      "action_name": "auto-stop_wl",
      "description": "获取/设置扫描终止波长",
      "description_en": "get/set the sweep stop wavelength"
    },
    {
      "action_name": "auto-wavelength",
      "description": "获取光谱数据的波长轴",
      "description_en": "get the wavelength axis of the spectral data"
    },
    {
      "action_name": "auto-channel",
      "description": "获取可用通道列表",
      "description_en": "get the list of available channels"
    }
  ],
  "tag_hints": [
    "optical spectrum analysis",
    "OSA",
    "wavelength sweep",
    "laser spectrum characterization",
    "fiber optics measurement",
    "spectral bandwidth measurement",
    "optical communication testing"
  ]
}

